int main(){unsigned*z,*o;float*out;ck(cudaMalloc(&z,sizeof(PACK_ZERO)));ck(cudaMalloc(&o,sizeof(PACK_ONE)));ck(cudaMalloc(&out,67*67*4));ck(cudaMemcpy(z,PACK_ZERO,sizeof(PACK_ZERO),cudaMemcpyHostToDevice));ck(cudaMemcpy(o,PACK_ONE,sizeof(PACK_ONE),cudaMemcpyHostToDevice));std::vector<float>reset(67*67,FLT_MAX),got(67*67);ck(cudaMemcpy(out,reset.data(),reset.size()*4,cudaMemcpyHostToDevice));epi<<<dim3(2,128),64>>>(z,o,out,67,3,3,7,15);ck(cudaDeviceSynchronize());for(int trial=1;trial<=5;++trial){ck(cudaMemcpy(out,reset.data(),reset.size()*4,cudaMemcpyHostToDevice));ck(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();for(int k=0;k<10;++k)epi<<<dim3(2,128),64>>>(z,o,out,67,3,3,7,15);ck(cudaDeviceSynchronize());double elapsed=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/10;ck(cudaMemcpy(got.data(),out,got.size()*4,cudaMemcpyDeviceToHost));double err=0;std::vector<double>data;for(unsigned x:INPUT_PREFIX)data.push_back(x);for(size_t k=0;k<got.size();++k){err=std::max(err,std::abs(double(got[k])-ORACLE[k]));data.push_back(got[k]);}bool ok=err<1e-3;std::string path="trial_"+std::to_string(trial)+".bin";FILE*f=fopen(path.c_str(),"wb");fwrite(data.data(),8,data.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.17g,\"timing_region\":\"ten_epi_kernel_mean\",\"jit_excluded\":true,\"internal_repeats\":10,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,elapsed,ok?"true":"false",data.size(),err,path.c_str(),data.size());if(!ok)return 3;}cudaFree(z);cudaFree(o);cudaFree(out);return 0;}
